pub fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since `a` is guaranteed non-empty, `iter().min()` will always return `Some(&i8)`.
    *a.iter().min().unwrap()
}

pub fn get_max_val(a: &Vec<i8>) -> i8 {
    // Since `a` is guaranteed non-empty, `iter().max()` will always return `Some(&i8)`.
    *a.iter().max().unwrap()
}

pub fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Assume `a` is non-empty and `q` is between 0 and 100 inclusive.
    // Sort the data so we can index into the proper quantile position.
    a.sort_unstable();

    let n = a.len();
    // Compute the index using the "inclusive" nearest‐rank method:
    //   index = floor(q/100 * (n - 1))
    // This yields 0 when q=0, and n-1 when q=100.
    let idx = (q as usize * (n - 1)) / 100;

    a[idx]
}

